const inv = $('Get Open Invoices').first().json;
const entries = inv.value || (Array.isArray(inv) ? inv : []);
const today = new Date().toISOString().slice(0, 10);
// Per-run override from the HubSpot page ("SW Make Job") beats the Settings node.
let ov = null; try { ov = $('SW Make Job').first().json; } catch (e) {}
let CUTOFF = '2024-12-31'; // must have a remaining invoice dated on/before this (blank = any overdue)
if (ov && ov.oldestInvoice !== undefined) { CUTOFF = String(ov.oldestInvoice).slice(0, 10); }
else { try { const v = $('Settings').first().json.Oldest_Open_Invoice; if (v !== undefined) CUTOFF = String(v == null ? '' : v).slice(0, 10); } catch (e) {} }
let MIN = 1000;
if (ov && ov.minBalance !== undefined && ov.minBalance !== '') { const m = Number(ov.minBalance); if (isFinite(m)) MIN = m; }
else { try { const v = Number($('Settings').first().json.Min_Overdue_Balance); if (isFinite(v)) MIN = v; } catch (e) {} }

const net = {};    // customerNo -> net past-due balance
const hasOld = {}; // customerNo -> has a remaining invoice dated <= CUTOFF
for (const e of entries) {
  const isOpen = e.Open === true || e.Open === 'true' || e.Open === 1;
  if (!isOpen) continue;
  const key = String(e.Customer_No);
  const remaining = Number(e.Remaining_Amount) || 0;
  const due = String(e.Due_Date || '').slice(0, 10);
  const doc = String(e.Document_Date || '').slice(0, 10);
  if (String(e.Document_Type) === 'Invoice') {
    if (remaining !== 0 && doc && (!CUTOFF || doc <= CUTOFF)) hasOld[key] = true;
    if (due && due < today) net[key] = (net[key] || 0) + remaining; // past-due invoice
  } else {
    net[key] = (net[key] || 0) + remaining; // open payment/credit (negative)
  }
}
// Counted: a remaining invoice dated 2024-or-older AND a net past-due balance that
// is positive AND at least the MIN threshold from the Settings node.
const nos = Object.keys(net).filter(
  (k) => hasOld[k] && Math.round(net[k] * 100) > 0 && Math.round(net[k] * 100) >= Math.round(MIN * 100)
);

// Nobody qualifies -> stop. On a webhook run, mark the job done-empty so the page
// stops waiting.
if (nos.length === 0) {
  try {
    let jobId = null; try { jobId = $('SW Make Job').first().json.jobId; } catch (e) {}
    if (jobId) { const sd = $getWorkflowStaticData('global'); sd['job_' + jobId] = { status: 'done', at: Date.now(), customers: 0, empty: true }; }
  } catch (e) {}
  return [];
}

// Chunk the customer numbers so each Get Customers request URL stays well under
// the length limit. ~40 numbers => a $filter of ~800 chars per request.
const CHUNK = 40;
const out = [];
for (let i = 0; i < nos.length; i += CHUNK) {
  const part = nos.slice(i, i + CHUNK);
  const customerFilter = part.map((n) => "No eq '" + n.replace(/'/g, "''") + "'").join(' or ');
  out.push({ json: { batch: i / CHUNK, count: nos.length, customerNos: part, customerFilter } });
}
return out;

/*
 * transform.js
 * ------------
 * Pure data transforms shared by the local test harness and the n8n Code node.
 * No I/O, no dependencies — safe to paste into an n8n Code node.
 *
 * Inputs (arrays of plain objects):
 *   customers[] (OData V4 Customer page):
 *     { No, Name, Address, Address_2, City, County, Post_Code, Balance_Due_LCY }
 *   entries[] (OData V4 CustomerLedgerEntries page — table 21):
 *     { Customer_No, Document_Type, Document_No, Document_Date, Due_Date,
 *       Amount, Remaining_Amount, Open }   // Open=true & Document_Type='Invoice' = unpaid invoice
 *
 * Output: one record per QUALIFYING customer (>=1 open invoice dated in the window):
 *   { customerNo, tokens{...seven merge tokens...}, statement{ lines[], total, balanceDue } }
 */

const WINDOW_START = "2023-01-01";
const WINDOW_END = "2024-12-31";

// Format a number as a USD amount WITHOUT the currency symbol: 1234.5 -> "1,234.50".
// The letter template already prints a literal "$" before {Converted_balance}.
function formatUSD(n) {
  const num = Number(n) || 0;
  return num.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

// Normalize a BC date (which may arrive as "2023-05-01" or full ISO) to YYYY-MM-DD.
function isoDate(d) {
  if (!d) return "";
  return String(d).slice(0, 10);
}

function inWindow(dateStr) {
  const d = isoDate(dateStr);
  return d >= WINDOW_START && d <= WINDOW_END;
}

// Map the BC Document_Type to a short label for the statement's "Document Type"
// column: Invoice / Credit / Payment / Refund (unknown types pass through as-is).
function displayDocType(type) {
  const t = String(type == null ? "" : type).trim();
  if (t === "Credit Memo" || t === "Credit") return "Credit";
  if (t === "Invoice") return "Invoice";
  if (t === "Payment") return "Payment";
  if (t === "Refund") return "Refund";
  return t;
}

/**
 * @param {Object[]} customers
 * @param {Object[]} entries     Customer Ledger Entries (OData V4 CustomerLedgerEntries)
 * @param {Object}   [options]
 * @param {string}   [options.today] ISO date used for the past-due test (default: today). An
 *        invoice is past due when its Due Date is strictly before this date.
 * @param {"filtered"|"balanceDue"} [options.amountSource="filtered"]
 *        "filtered"   -> Converted_balance = past-due invoices minus open credits/payments
 *        "balanceDue" -> Converted_balance = customer's Balance_Due_LCY (total open balance)
 *
 * Counted customers = those with a POSITIVE net past-due balance. The statement lists the
 * past-due invoices plus open credits/payments (negative lines); the total nets to the letter
 * amount.
 * @returns {Object[]} qualifying customer records
 */
function buildRecords(customers, entries, options = {}) {
  const amountSource = options.amountSource || "filtered";
  // "Past due" = an open invoice whose Due Date is strictly before `today`.
  const today = options.today || new Date().toISOString().slice(0, 10);
  // A customer is counted only if they have an open invoice with remaining balance
  // dated on/before this cutoff (default 2024 or older). BLANK ("") drops the age
  // rule so any overdue invoice qualifies.
  const qualifyCutoff = options.qualifyCutoff == null
    ? "2024-12-31"
    : String(options.qualifyCutoff).slice(0, 10);
  // Minimum net past-due balance to include a customer (default 0). The workflow's
  // "Settings" node sets this to 1000 so only customers owing >= $1,000 get a letter.
  const minBalance = Number(options.minBalance) || 0;
  // Exclude customers whose default route (Customer.Shipping_Agent_Code) matches this
  // (default "RT 21"). Fail-open: a missing/blank route is never excluded.
  const normRoute = (s) => String(s == null ? "" : s).toUpperCase().replace(/[^A-Z0-9]/g, "");
  const excludeRoute = options.excludeRoute === null ? "" : normRoute(options.excludeRoute || "RT 21");

  // Index customers by their number for O(1) join.
  const custByNo = new Map();
  for (const c of customers || []) custByNo.set(String(c.No), c);

  // First ship-to per customer = the default; used for the shipping-address PDF.
  const shipByNo = new Map();
  for (const st of options.shipTos || []) {
    const k = String(st.HFSCustomerNo);
    if (!shipByNo.has(k)) shipByNo.set(k, st);
  }

  // Per customer, collect: PAST-DUE invoice lines, plus OPEN credit/payment lines
  // (any date). Non-invoice open entries (Payment/Credit Memo/Refund) are credits
  // with a negative Remaining_Amount that reduce the balance. `hasOld` flags an open
  // invoice with remaining dated on/before the qualify cutoff.
  const grouped = new Map(); // customerNo -> { lines[], total, hasOld }
  for (const e of entries || []) {
    const isOpen = e.Open === true || e.Open === "true" || e.Open === 1;
    if (!isOpen) continue;

    const type = String(e.Document_Type);
    const remaining = Number(e.Remaining_Amount) || 0;
    const documentDate = isoDate(e.Document_Date);
    const dueDate = isoDate(e.Due_Date);
    const key = String(e.Customer_No);
    if (!grouped.has(key)) grouped.set(key, { lines: [], total: 0, hasOld: false });
    const g = grouped.get(key);

    if (type === "Invoice") {
      // Qualify gate: an open invoice with a remaining balance dated <= cutoff.
      // Blank cutoff -> any remaining invoice satisfies the gate.
      if (remaining !== 0 && documentDate && (!qualifyCutoff || documentDate <= qualifyCutoff)) g.hasOld = true;
      // Statement shows only PAST-DUE invoices.
      if (dueDate && dueDate < today) {
        g.total += remaining;
        g.lines.push({
          documentDate, docType: "Invoice",
          orderNo: e.Description || "", documentNo: e.Document_No || "",
          dueDate, remaining, kind: "invoice",
        });
      }
    } else {
      // Open payment/credit/refund — an unapplied credit, included regardless of date.
      g.total += remaining;
      g.lines.push({
        documentDate, docType: displayDocType(type),
        orderNo: e.Order_No || "", documentNo: e.Document_No || "",
        dueDate, remaining, kind: "credit",
      });
    }
  }

  const records = [];
  for (const [customerNo, g] of grouped) {
    // Counted only if they have a remaining invoice dated 2024-or-older AND a
    // positive net past-due balance that meets the minimum threshold.
    if (!g.hasOld) continue;
    if (Math.round(g.total * 100) <= 0) continue;
    if (Math.round(g.total * 100) < Math.round(minBalance * 100)) continue;

    const c = custByNo.get(customerNo) || {};
    // Exclude the RT 21 route (from the customer's default Shipping_Agent_Code).
    if (excludeRoute && normRoute(c.Shipping_Agent_Code) === excludeRoute) continue;
    const balanceDue = Number(c.Balance_Due_LCY) || 0;
    const amount = amountSource === "balanceDue" ? balanceDue : g.total;
    const Converted_balance = formatUSD(amount);
    const name = c.Name || customerNo;

    const lines = g.lines.sort((a, b) =>
      a.documentDate < b.documentDate ? -1 : a.documentDate > b.documentDate ? 1 : 0
    );

    const tokens = {
      Description: name, AccountNumber: customerNo,
      Address_1: c.Address || "", Address_2: c.Address_2 || "",
      City: c.City || "", State: c.County || "", Zipcode: c.Post_Code || "",
      Converted_balance,
    };
    // Shipping tokens: default ship-to address (fall back to billing when none).
    const st = shipByNo.get(customerNo);
    const shipTokens = st
      ? {
          Description: name, AccountNumber: customerNo,
          Address_1: st.Address || "", Address_2: st.Address_2 || "",
          City: st.City || "", State: st.County || st.State || "", Zipcode: st.Post_Code || "",
          Converted_balance,
        }
      : { ...tokens };

    records.push({ customerNo, tokens, shipTokens, statement: { lines, total: g.total, balanceDue } });
  }

  // Deterministic order: by customer name.
  records.sort((a, b) => a.tokens.Description.localeCompare(b.tokens.Description));
  return records;
}

// --- n8n driver -------------------------------------------------------------
// Get Customers runs once per batch (chunked to keep each URL short), so combine
// the .value array from every Get Customers item.
const customers = $('Get Customers').all().flatMap((it) => {
  const j = it.json;
  return j.value || (Array.isArray(j) ? j : j && j.No ? [j] : []);
});
// Ship-to addresses (for the shipping-address PDF); combine every batch's .value.
let shipTos = [];
try {
  shipTos = $('Get Ship-to Addresses').all().flatMap((it) => {
    const j = it.json;
    return j.value || (Array.isArray(j) ? j : j && j.HFSCustomerNo ? [j] : []);
  });
} catch (e) { shipTos = []; }
const invResp = $('Get Open Invoices').first().json;
const entries = invResp.value || (Array.isArray(invResp) ? invResp : []);

// Per-run override from the HubSpot page ("SW Make Job", webhook runs only) beats
// the manual Settings node.
let ov = null; try { ov = $('SW Make Job').first().json; } catch (e) {}
let minBalance = 1000;
if (ov && ov.minBalance !== undefined && ov.minBalance !== '') { const m = Number(ov.minBalance); if (isFinite(m)) minBalance = m; }
else { try { const v = Number($('Settings').first().json.Min_Overdue_Balance); if (isFinite(v)) minBalance = v; } catch (e) {} }
let qualifyCutoff = '2024-12-31';
if (ov && ov.oldestInvoice !== undefined) { qualifyCutoff = String(ov.oldestInvoice).slice(0, 10); }
else { try { const v = $('Settings').first().json.Oldest_Open_Invoice; if (v !== undefined) qualifyCutoff = String(v == null ? '' : v).slice(0, 10); } catch (e) {} }

const records = buildRecords(customers, entries, { amountSource: 'filtered', shipTos, minBalance, qualifyCutoff });
return records.map((r) => ({ json: r }));

/*
 * pure-pdf.js
 * -----------
 * Zero-dependency PDF generator. Emits the past-due letter + statement as ONE
 * multi-page PDF per customer using the base-14 fonts (no embedding, no modules,
 * no external service) — so it runs inside an n8n Cloud Code node as-is.
 *
 * Exports buildCustomerPdf(tokens, statement, opts) -> Buffer.
 *
 * Font widths are approximated (slightly generous) purely for line-wrapping and
 * centering; glyph rendering itself is exact (the viewer uses the real metrics).
 */

// --- WinAnsi text encoding + PDF string escaping ---------------------------
function toWin(s) {
  return String(s == null ? "" : s)
    .replace(/–/g, "\x96") // en dash
    .replace(/—/g, "\x97") // em dash
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/…/g, "...");
}
function esc(s) {
  return toWin(s).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

// Approximate glyph width in em units (generous, so lines never overflow).
function emWidth(ch) {
  if (ch === " ") return 0.3;
  if ("iljI.,:;'!|`".includes(ch)) return 0.3;
  if ("ftr()[]-".includes(ch)) return 0.4;
  if ("mwMW".includes(ch)) return 0.92;
  if (ch >= "A" && ch <= "Z") return 0.72;
  if (ch >= "0" && ch <= "9") return 0.56;
  return 0.53;
}
function approxWidth(s, size) {
  let w = 0;
  for (const ch of toWin(s)) w += emWidth(ch);
  return w * size;
}
function wrap(text, size, maxWidth) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let cur = "";
  for (const w of words) {
    const trial = cur ? cur + " " + w : w;
    if (approxWidth(trial, size) > maxWidth && cur) {
      lines.push(cur);
      cur = w;
    } else cur = trial;
  }
  if (cur) lines.push(cur);
  return lines;
}

// --- content-stream draw helpers -------------------------------------------
// Fonts: F1 Helvetica, F2 Helvetica-Bold, F3 Times-Roman, F4 Times-Bold
function text(x, y, s, font, size, gray) {
  const col = gray != null ? `${gray} g ` : "0 g ";
  return `${col}BT /${font} ${size} Tf 1 0 0 1 ${x.toFixed(2)} ${y.toFixed(2)} Tm (${esc(s)}) Tj ET\n`;
}
function hline(x1, x2, y) {
  return `0.6 G 0.7 w ${x1.toFixed(2)} ${y.toFixed(2)} m ${x2.toFixed(2)} ${y.toFixed(2)} l S\n`;
}

const PAGE_W = 612, PAGE_H = 792, MARGIN = 72;
const HEAD = "ENGELMAN'S BAKERY";

// --- FPi 700 / #10 window envelope geometry ---------------------------------
// See docs/fpi-700-fold-spec.md. The FPi 700 letter-folds the sheet into three
// ~264 pt panels, and the address must land in whichever panel faces the
// envelope window.
//
// The offsets within that panel come from the #10 aperture. The safe zone is
// smaller than the window itself, because the folded piece floats inside the
// envelope: 0.458" of vertical slack (a 3.667" piece in a 4.125" envelope) and
// 1.0" horizontal. The address has to stay visible at EVERY position the piece
// can take, not just resting at the bottom, so these bounds are the
// intersection of the extremes rather than the aperture:
//
//   window aperture   1.125" x 4.5", inset 0.875" left / 0.5" bottom
//   minus the slack   ->  36-84 pt above the panel's bottom edge,  x 63-315 pt
//
// The PANEL is the TOP third, confirmed by folding real output: the statement's
// bill-to block sits at y 568.77-625.77 and lands in the window, which is only
// possible if Panel C faces out. With the measured fold correction below the
// window band is y 588-636.
// (An earlier revision assumed the bottom panel. The offsets were right; the
// panel was not.) To re-target a panel, change WINDOW_PANEL_BASE alone.
//
// Nothing but the address may print inside that band, across the FULL width of
// the panel — the piece slides sideways, so anything level with the window can
// slide into view even if it starts clear of it.
const PANEL_H = 264;                        // one C-fold third of an 11" sheet
const WINDOW_PANEL_BASE = 2 * PANEL_H;      // Panel A = 0, B = PANEL_H, C = 2 * PANEL_H

// Measured on the machine with production envelopes: the block landed two lines
// (24 pt) low in the real window, so the actual crease sits ~24 pt off the
// nominal third — the fold plates are touchscreen-adjustable and evidently set
// that way. The aperture offsets above are geometry; this is the empirical
// correction, kept separate so the two stay legible. It is corroborated by the
// statement's bill-to block, which reads correctly in the window at a top
// baseline of 625.77 — 22.3 pt above where the address block was sitting.
// If the fold plates are ever re-set, nudge THIS number and nothing else.
const FOLD_CALIBRATION = 24;
const WINDOW_Y_MIN = WINDOW_PANEL_BASE + 36 + FOLD_CALIBRATION;   // 588
const WINDOW_Y_MAX = WINDOW_PANEL_BASE + 84 + FOLD_CALIBRATION;   // 636
const WINDOW_X_MAX = 315;

// Embedded brand logo (baseline JPEG). Populated by scripts/embed-logo.js.
const LOGO = { w: 263, h: 53, b64: "" };

// Draw the letterhead centered at the top: the logo image if present, else grey text.
// Returns { content, bottom } where `bottom` is the y just below the header.
function header(topY, dispW, textSize) {
  if (LOGO && LOGO.b64) {
    const w = dispW;
    const h = dispW * (LOGO.h / LOGO.w);
    const x = (PAGE_W - w) / 2;
    const bottom = topY - h;
    const content =
      `q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${bottom.toFixed(2)} cm /Im0 Do Q\n`;
    return { content, bottom };
  }
  const size = textSize || 22;
  const w = approxWidth(HEAD, size);
  return { content: text((PAGE_W - w) / 2, topY - size, HEAD, "F4", size, "0.5"), bottom: topY - size };
}

// --- letter (2 pages: body, then the window address) ------------------------
function letterPages(t) {
  const cw = PAGE_W - 2 * MARGIN;
  const size = 11, lh = 15;

  // Page 1
  const h1 = header(PAGE_H - MARGIN, 170, 22);
  let c = h1.content;
  let y = h1.bottom - 30;
  c += text(MARGIN, y, "Subject:", "F4", size);
  c += text(MARGIN + approxWidth("Subject:  ", size), y, "Past Due Balance – Immediate Attention Required", "F3", size);
  y -= lh + 12;
  c += text(MARGIN, y, `Dear ${t.Description},`, "F3", size);
  y -= lh + 12;

  const paras = [
    `We are writing to inform you that your account with Engelman's Bakery is currently past due. As of today, your overdue balance is $${t.Converted_balance}. We have enclosed an account statement for your convenience.`,
    "We kindly request that you remit payment in full to satisfy your payment obligation. Please contact us at 770-248-1444 ext. 2 to arrange payment or discuss any questions regarding your account. If the account is not paid, further collection proceedings will be taken.",
    "We appreciate your prompt attention to this matter and look forward to resolving it quickly.",
  ];
  for (const p of paras) {
    for (const ln of wrap(p, size, cw)) {
      c += text(MARGIN, y, ln, "F3", size);
      y -= lh;
    }
    y -= 10;
  }
  y -= 12;
  c += text(MARGIN, y, "Best Regards,", "F3", size); y -= lh;
  c += text(MARGIN, y, "Engelman's Bakery", "F3", size); y -= lh;
  c += text(MARGIN, y, "770-248-1444", "F3", size);

  // Page 2 — mailing address block, centered in the #10 window's safe band. The
  // band is in the TOP panel, so the block sits high on the page, level with the
  // statement's bill-to block on the following sheet. The letterhead is the only
  // other ink on this page and clears the band by ~74 pt.
  let c2 = header(PAGE_H - MARGIN, 170, 22).content;
  const addr = [
    t.Description,
    t.Address_1,
    t.Address_2,
    cityStateZip(t),
  ].map(clean).filter(Boolean);

  // 10/12 rather than the letter's 11/15: a four-line address at 15 pt leading
  // fills the 48 pt band exactly, leaving nothing for fold variance.
  let asize = 10;
  const alh = 12;
  // Shrink rather than let a long customer name run past the window's right
  // edge as the piece slides. approxWidth is deliberately generous, so this
  // errs toward shrinking early.
  while (asize > 7 && addr.some((l) => approxWidth(l, asize) > WINDOW_X_MAX - MARGIN)) asize -= 0.5;

  // Center the block in the band so 3- and 4-line addresses both clear the
  // aperture. Ink runs from roughly 0.22em below the baseline to 0.73em above.
  const desc = asize * 0.22, capH = asize * 0.73;
  const inkH = (addr.length - 1) * alh + capH + desc;
  let ay = (WINDOW_Y_MIN + WINDOW_Y_MAX) / 2 - inkH / 2 + desc + (addr.length - 1) * alh;
  for (const ln of addr) {
    c2 += text(MARGIN, ay, ln, "F3", asize);
    ay -= alh;
  }
  return [c, c2];
}

// --- statement (1+ pages) ---------------------------------------------------
function formatUSD(n) {
  const num = Number(n) || 0;
  return num.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
// Signed dollar amount: 1234.5 -> "$1,234.50", -200 -> "-$200.00".
function money(n) {
  const num = Number(n) || 0;
  return (num < 0 ? "-$" : "$") + formatUSD(Math.abs(num));
}
// --- address hygiene --------------------------------------------------------
// Business Central returns placeholder junk where an address was never filled
// in — the 2026-08-13 run mailed two envelopes whose entire city/state/ZIP line
// was a single "-". Treat those markers as empty rather than printing them.
const PLACEHOLDER = /^(?:[-–—.,_/\\*?]+|n\/?a|none|null|nil|unknown|unk|tbd|test)$/i;
function clean(v) {
  const s = String(v == null ? "" : v).trim().replace(/\s+/g, " ");
  return PLACEHOLDER.test(s) ? "" : s;
}

// USPS state for a ZIP code. Business Central's County field is empty across the
// whole customer list, and ship-to records carry no state field at all, so the
// ZIP is the only place a state can come from. These are the USPS 3-digit prefix
// allocations; first match wins, and an unallocated prefix returns "" so the
// address gets flagged rather than mislabelled.
const ZIP_STATE = [
  [5, 5, "NY"], [6, 9, "PR"], [10, 27, "MA"], [28, 29, "RI"], [30, 38, "NH"],
  [39, 49, "ME"], [50, 59, "VT"], [60, 69, "CT"], [70, 89, "NJ"], [90, 98, "AE"],
  [100, 149, "NY"], [150, 196, "PA"], [197, 199, "DE"], [200, 200, "DC"],
  [201, 201, "VA"], [202, 205, "DC"], [206, 219, "MD"], [220, 246, "VA"],
  [247, 268, "WV"], [270, 289, "NC"], [290, 299, "SC"], [300, 319, "GA"],
  [320, 339, "FL"], [340, 340, "AA"], [341, 349, "FL"], [350, 369, "AL"],
  [370, 385, "TN"], [386, 397, "MS"], [398, 399, "GA"], [400, 427, "KY"],
  [430, 459, "OH"], [460, 479, "IN"], [480, 499, "MI"], [500, 528, "IA"],
  [530, 549, "WI"], [550, 567, "MN"], [570, 577, "SD"], [580, 588, "ND"],
  [590, 599, "MT"], [600, 629, "IL"], [630, 658, "MO"], [660, 679, "KS"],
  [680, 693, "NE"], [700, 714, "LA"], [716, 729, "AR"], [730, 749, "OK"],
  [750, 799, "TX"], [800, 816, "CO"], [820, 831, "WY"], [832, 838, "ID"],
  [840, 847, "UT"], [850, 865, "AZ"], [870, 884, "NM"], [885, 885, "TX"],
  [889, 898, "NV"], [900, 961, "CA"], [962, 966, "AP"], [967, 968, "HI"],
  [969, 969, "GU"], [970, 979, "OR"], [980, 994, "WA"], [995, 999, "AK"],
];
function zip5(v) {
  const m = /(\d{5})/.exec(String(v == null ? "" : v));
  return m ? m[1] : "";
}
function stateFromZip(v) {
  const z = zip5(v);
  if (!z) return "";
  const p = Number(z.slice(0, 3));
  for (const r of ZIP_STATE) if (p >= r[0] && p <= r[1]) return r[2];
  return "";
}

// "City, State Zip" — junk-tolerant, and fills the state in from the ZIP when
// the source data has none (which is every record).
function cityStateZip(t) {
  const x = t || {};
  const cs = [clean(x.City), clean(x.State) || stateFromZip(x.Zipcode)].filter(Boolean).join(", ");
  return [cs, clean(x.Zipcode)].filter(Boolean).join(" ");
}

// Why a mail piece can't be delivered, or null when it can.
// USPS routes on the ZIP, so a missing state is a formatting defect (fixed
// above) rather than a delivery blocker — but no ZIP AND no city/state leaves
// the envelope with nowhere to go, and no street line leaves it with no
// delivery point. Those get pulled from the run instead of being mailed blind.
function addressProblem(t) {
  const x = t || {};
  if (!clean(x.Description)) return "missing customer name";
  if (!clean(x.Address_1) && !clean(x.Address_2)) return "missing street address";
  const city = clean(x.City);
  const state = clean(x.State) || stateFromZip(x.Zipcode);
  if (!zip5(x.Zipcode) && !(city && state)) return "missing ZIP and city/state";
  return null;
}
function statementPages(t, statement, opts) {
  const asOf = (opts && opts.asOfDate) || new Date().toISOString().slice(0, 10);
  // Left edges spread evenly across the content width (72..540) so the six columns
  // are balanced — no left-side crowding and no dead gap before the right-aligned
  // Remaining Balance column.
  const cols = [
    { key: "documentDate", label: "Document Date", x: MARGIN },
    { key: "docType", label: "Document Type", x: MARGIN + 84 },
    { key: "documentNo", label: "Document No.", x: MARGIN + 164 },
    { key: "orderNo", label: "Order No.", x: MARGIN + 241 },
    { key: "dueDate", label: "Due Date", x: MARGIN + 339 },
    { key: "remaining", label: "Remaining Balance", x: MARGIN + 410, money: true, right: PAGE_W - MARGIN },
  ];
  const size = 8, lh = 14;

  const pages = [];
  let c = "";
  let y;
  const startPage = (withHeader) => {
    const hd = header(PAGE_H - MARGIN, 150, 20);
    c = hd.content;
    y = hd.bottom - 34; // extra space between the logo and the title
    const title = "Past Due Invoices";
    c += text((PAGE_W - approxWidth(title, 16)) / 2, y, title, "F4", 16);
    y -= 30;
    if (withHeader) {
      c += text(MARGIN, y, `Statement Date: ${asOf}`, "F1", 10); y -= 18;
      // Bill-to block: Company Name, Account Number, then address.
      const bill = [
        t.Description,
        clean(t.AccountNumber) ? "Account Number: " + clean(t.AccountNumber) : null,
        t.Address_1,
        t.Address_2,
        cityStateZip(t),
      ].map(clean).filter(Boolean);
      for (const l of bill) { c += text(MARGIN, y, l, "F1", 10); y -= 13; }
      y -= 18;
    }
    // column header
    for (const col of cols) {
      if (col.right) c += text(col.right - approxWidth(col.label, size), y, col.label, "F2", size);
      else c += text(col.x, y, col.label, "F2", size);
    }
    y -= 5;
    c += hline(MARGIN, PAGE_W - MARGIN, y);
    y -= 13;
  };

  startPage(true);
  for (const ln of statement.lines) {
    if (y < 110) { pages.push(c); startPage(false); }
    for (const col of cols) {
      const v = col.money ? money(ln[col.key]) : String(ln[col.key] || "");
      if (col.right) c += text(col.right - approxWidth(v, size), y, v, "F1", size);
      else c += text(col.x, y, v, "F1", size);
    }
    y -= lh;
  }
  y -= 4;
  c += hline(MARGIN, PAGE_W - MARGIN, y);
  y -= 16;
  const totLabel = "Total Past Due:";
  const totVal = money(statement.total);
  c += text(MARGIN + 300, y, totLabel, "F2", 10);
  c += text((PAGE_W - MARGIN) - approxWidth(totVal, 10), y, totVal, "F2", 10);
  pages.push(c);
  return pages;
}

// --- low-level PDF assembler ------------------------------------------------
// Memory-conscious: streams every object into a chunk array (each chunk becomes a
// small Buffer, joined once at the end) instead of growing one multi-MB string,
// and frees each page's content as soon as it is serialized. This keeps peak
// memory near one copy of the output — important for large batches inside the
// memory-capped n8n Cloud Code node. All emitted text is latin1 (bytes 0-255),
// so a string's .length equals its byte length and can drive the xref offsets.
function buildPdf(pageContents, docOpts) {
  const title = docOpts && docOpts.title;
  const P = pageContents.length;
  const offsets = [];
  const chunks = [];
  let pos = 0;
  const push = (s) => { chunks.push(s); pos += s.length; };
  push("%PDF-1.4\n%\xe2\xe3\xcf\xd3\n");
  const emit = (num, body) => {
    offsets[num] = pos;
    push(`${num} 0 obj\n${body}\nendobj\n`);
  };
  // Optional logo image XObject is object 7; content/page objects start after it.
  const hasLogo = !!(LOGO && LOGO.b64);
  const imgObj = 7;
  const base = hasLogo ? 7 : 6; // last non-page object number
  const xobjRes = hasLogo ? ` /XObject << /Im0 ${imgObj} 0 R >>` : "";

  const pageNums = [];
  for (let i = 0; i < P; i++) pageNums.push(base + 2 + i * 2);

  emit(1, "<< /Type /Catalog /Pages 2 0 R >>");
  emit(2, `<< /Type /Pages /Kids [ ${pageNums.map((n) => n + " 0 R").join(" ")} ] /Count ${P} >>`);
  emit(3, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
  emit(4, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
  emit(5, "<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman /Encoding /WinAnsiEncoding >>");
  emit(6, "<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold /Encoding /WinAnsiEncoding >>");
  if (hasLogo) {
    const jpeg = Buffer.from(LOGO.b64, "base64").toString("latin1");
    emit(
      imgObj,
      `<< /Type /XObject /Subtype /Image /Width ${LOGO.w} /Height ${LOGO.h} ` +
        `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\n` +
        `stream\n${jpeg}\nendstream`
    );
  }
  for (let i = 0; i < P; i++) {
    const contentNum = base + 1 + i * 2;
    const pageNum = base + 2 + i * 2;
    const content = pageContents[i];
    pageContents[i] = null; // release the source string once we've consumed it
    emit(contentNum, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
    emit(
      pageNum,
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] ` +
        `/Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R /F4 6 0 R >>${xobjRes} >> /Contents ${contentNum} 0 R >>`
    );
  }
  // Optional document Title (shows in the PDF viewer's title bar / tab).
  let infoObj = 0;
  if (title) {
    infoObj = base + 2 * P + 1;
    emit(infoObj, `<< /Title (${esc(title)}) >>`);
  }
  const lastObj = base + 2 * P + (infoObj ? 1 : 0);
  const xrefOffset = pos;
  let xref = `xref\n0 ${lastObj + 1}\n0000000000 65535 f \n`;
  for (let n = 1; n <= lastObj; n++) {
    xref += String(offsets[n] || 0).padStart(10, "0") + " 00000 n \n";
  }
  push(xref);
  const infoRef = infoObj ? ` /Info ${infoObj} 0 R` : "";
  push(`trailer\n<< /Size ${lastObj + 1} /Root 1 0 R${infoRef} >>\nstartxref\n${xrefOffset}\n%%EOF\n`);
  // Join once. Small per-chunk Buffers avoid a giant intermediate latin1 string.
  const out = Buffer.concat(chunks.map((c) => Buffer.from(c, "latin1")));
  chunks.length = 0;
  return out;
}

// --- fitting a set onto exactly two sheets ----------------------------------
// The FPi 700 has no OMR, so it separates customers by counting a FIXED number
// of sheets. A set that runs long does not merely look wrong: the machine still
// takes two sheets, so every LATER customer's pages shift into the wrong
// envelope, disclosing one customer's balance to another. It fails silently and
// is undetectable until the mail is opened. See docs/fpi-700-fold-spec.md §4.
const LETTER_PAGES = 2;          // letter front, address back (one duplex sheet)
const STATEMENT_MAX_PAGES = 2;   // one duplex sheet
const SET_PAGES = LETTER_PAGES + STATEMENT_MAX_PAGES;

// Collapse the oldest lines into a single "Balance Forward" row, keeping the
// `keep` most recent in full detail. Lines arrive oldest-first (transform.js
// sorts by document date), and statement.total is untouched, so the amount owed
// still reconciles against the detail plus the carried-forward row.
function condenseStatement(s, keep) {
  const lines = s.lines || [];
  if (keep >= lines.length) return s;
  const old = lines.slice(0, lines.length - keep);
  const forward = {
    documentDate: old[0].documentDate || "",
    docType: "Balance Forward",
    documentNo: old.length + " earlier invoice" + (old.length === 1 ? "" : "s"),
    orderNo: "",
    dueDate: "",
    remaining: old.reduce((a, l) => a + (Number(l.remaining) || 0), 0),
  };
  return Object.assign({}, s, { lines: [forward, ...lines.slice(lines.length - keep)] });
}

// Render the statement within `maxPages`, condensing the oldest detail lines if
// it would otherwise overflow. Returns null only when even a fully condensed
// statement does not fit — the caller must then divert the customer rather than
// emit a third sheet.
function fitStatementPages(t, s, o, maxPages) {
  const pages = statementPages(t, s, o);
  if (pages.length <= maxPages) return { pages, condensed: 0 };
  // Page count is monotonic in the number of detail lines kept, so binary-search
  // the largest `keep` that still fits rather than re-rendering once per line.
  let lo = 0, hi = (s.lines || []).length - 1, best = null;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const p = statementPages(t, condenseStatement(s, mid), o);
    if (p.length <= maxPages) {
      best = { pages: p, condensed: s.lines.length - mid };
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return best;
}

// Page-content array for one customer: the letter (sheet 1) then the statement
// (sheet 2). For double-sided printing this is ALWAYS exactly SET_PAGES pages,
// so the letters land on pages 1, 5, 9, ... and each customer occupies exactly
// two sheets in the inserter. Returns null when the statement cannot be made to
// fit — that customer must be diverted, never padded out to a third sheet.
// With pad:false (the compact on-screen copy) there is no machine to satisfy, so
// the statement runs as long as it needs to.
// Null-safe: a missing tokens/statement can never throw (renders empty fields).
function customerPages(tokens, statement, opts) {
  const o = opts || {};
  const pad = o.pad !== false; // pad:false -> compact copy (no blank filler pages)
  const t = tokens || {};
  const s = statement && statement.lines ? statement : { lines: [], total: 0 };
  const letter = letterPages(t);
  if (pad && letter.length % 2 === 1) letter.push(""); // pad the letter to a full sheet
  if (!pad) return [...letter, ...statementPages(t, s, o)];
  const fit = fitStatementPages(t, s, o, STATEMENT_MAX_PAGES);
  if (!fit) return null;
  const stmt = fit.pages;
  while (stmt.length < STATEMENT_MAX_PAGES) stmt.push(""); // fill out the sheet
  return [...letter, ...stmt];
}

// Normalize an address token set to a comparable key (case/space-insensitive).
// Uses the same cleaning and ZIP-derived state as the rendered address, so a
// ship-to isn't treated as "different" purely because one side is missing a
// state or carries a placeholder where the other is blank.
function normAddr(t) {
  const x = t || {};
  return [x.Address_1, x.Address_2, x.City, clean(x.State) || stateFromZip(x.Zipcode), x.Zipcode]
    .map((v) => clean(v).toLowerCase())
    .join("|");
}
// True when two token sets carry the same mailing address (ignores Description).
// Used to skip customers whose shipping address equals billing from the shipping PDF.
function sameAddress(a, b) {
  return normAddr(a) === normAddr(b);
}

// One PDF (letter + statement) for a single customer.
function buildCustomerPdf(tokens, statement, opts) {
  const pages = customerPages(tokens, statement, opts);
  if (!pages) throw new Error("statement does not fit one sheet: " + ((tokens && tokens.Description) || "unknown customer"));
  return buildPdf(pages);
}

// One combined batch PDF for a list of records. tokenKey selects the address set:
// "tokens" (billing, default) or "shipTokens" (shipping).
//
// Pass opts.excluded as an array to collect customers whose statement could not
// be condensed onto one sheet; they are left out of the machine run and must be
// stuffed by hand. Without the sink they are still excluded, just not reported.
function buildBatchPdf(records, opts, tokenKey) {
  const key = tokenKey || "tokens";
  const o = opts || {};
  const pad = o.pad !== false;
  const pages = [];
  let included = 0;
  for (const r of records || []) {
    const tok = r && (r[key] || r.tokens);
    if (!tok) continue; // skip malformed records instead of crashing
    // An undeliverable address is undeliverable however well the sheet folds:
    // pull it from the run rather than spend an envelope on it.
    const bad = addressProblem(tok);
    if (bad) {
      if (o.excluded) o.excluded.push({ name: clean(tok.Description), reason: bad });
      continue;
    }
    const p = customerPages(tok, r.statement, o);
    if (!p) {
      if (o.excluded) o.excluded.push({ name: clean(tok.Description), reason: "statement exceeds one sheet" });
      continue;
    }
    pages.push(...p);
    included++;
  }
  // Last line of defence. The machine counts sheets, so a set of the wrong length
  // mis-stuffs every envelope after it — fail the run rather than print mail that
  // goes to the wrong people.
  if (pad && pages.length !== included * SET_PAGES) {
    throw new Error(
      `set-length invariant violated: ${pages.length} pages for ${included} customers (expected ${included * SET_PAGES})`
    );
  }
  return buildPdf(pages, o);
}

// --- n8n driver -------------------------------------------------------------
// Two PDFs per account - Letter and Statement - rather than the printing workflow's two
// combined packs, Billing and Shipping.
//
// This is the ONLY part that differs from Printing Letter_Invoices. Every page-building
// helper above is identical, so the letters and statements look exactly like the printed
// ones. The printing workflow pads each customer out to a whole number of sheets so the
// double-sided run folds into envelopes correctly; an attachment needs no blank filler
// pages, so this passes pad:false.
//
// Where billing and shipping addresses differ, the letter carries both address variants
// and the statement is repeated once per variant, so each packet stays self-contained.
const all = items.map((i) => i.json);
// Defensive: only render records that actually carry tokens, so one malformed or stale
// item can never crash the whole batch.
const records = all.filter((r) => r && r.tokens);
const skipped = all.length - records.length;

const today = new Date().toISOString().slice(0, 10);
const o = { pad: false };
const out = [];
const excluded = [];

// Recipient addresses come from the Customer page this workflow already queries, rather
// than a separate contact lookup: Customer is published as a web service and proven to
// work here, and an endpoint that is not published fails the whole run.
const emailByAccount = new Map();
for (const it of $('Get Customers').all()) {
  const rows = Array.isArray(it.json && it.json.value) ? it.json.value : [it.json];
  for (const c of rows) {
    if (c && c.No) emailByAccount.set(String(c.No).trim(), clean(c.E_Mail).trim());
  }
}

for (const rec of records) {
  const billing = rec.tokens;
  const accountNumber = clean(billing.AccountNumber);
  const name = clean(billing.Description);

  if (!accountNumber) {
    excluded.push({ name, reason: "no account number" });
    continue;
  }

  // An undeliverable address still matters: the letter prints an address block, and a
  // blank one means the customer record needs fixing before they are chased.
  const problem = addressProblem(billing);
  if (problem) {
    excluded.push({ accountNumber, name, reason: problem });
    continue;
  }

  const statement = rec.statement && rec.statement.lines ? rec.statement : { lines: [], total: 0 };

  // Billing, plus shipping only when it genuinely differs. sameAddress is the same
  // comparison the printing workflow uses to decide who goes in the Shipping pack, so the
  // two agree on what "different" means.
  const variants = [billing];
  if (rec.shipTokens && !sameAddress(billing, rec.shipTokens)) variants.push(rec.shipTokens);

  const letterContents = [];
  const statementContents = [];
  for (const t of variants) {
    letterContents.push(...letterPages(t));
    statementContents.push(...statementPages(t, statement, o));
  }

  const letterFileName = `Letter_${accountNumber}_${today}.pdf`;
  const statementFileName = `Statement_${accountNumber}_${today}.pdf`;

  // Emitted as base64 in JSON rather than as binary: these items pass through HTTP Request
  // nodes on the way to the draft, which do not carry binary through, and the Graph
  // message payload wants base64 anyway.
  out.push({
    json: {
      accountNumber,
      accountName: name,
      recipientEmail: emailByAccount.get(accountNumber) || "",
      addressVariants: variants.length,
      letterPageCount: letterContents.length,
      statementPageCount: statementContents.length,
      balanceDue: statement.total,
      letterFileName,
      statementFileName,
      letterBase64: Buffer.from(
        buildPdf(letterContents, { title: "Past Due Letter " + accountNumber })).toString("base64"),
      statementBase64: Buffer.from(
        buildPdf(statementContents, { title: "Past Due Statement " + accountNumber })).toString("base64"),
      skipped,
      excluded,
    },
  });
}

if (out.length === 0) {
  throw new Error(
    `No customers to draft for: ${records.length} qualifying record(s), ${excluded.length} excluded.`
  );
}

return out;

// Build the Microsoft Graph message payload for the draft.
//
// Same payload shape the RT 21 - Daily Email workflow uses, except it is POSTed to
// /me/messages rather than /me/sendMail, which creates an unsent draft.
const json = $input.item.json;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (v) => typeof v === 'number'
  ? '$' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
  : null;

const balance = money(json.balanceDue);

// The letter is a PDF, so it cannot be the HTML body. The body is a short cover note and
// the letter is read from its attachment.
const html =
  '<div style="font:14px Segoe UI,Arial,sans-serif;color:#1a1a1a">' +
  `<p>Dear ${esc(json.accountName) || 'Customer'},</p>` +
  "<p>Your account with Engelman's Bakery is currently past due" +
  (balance ? `, with an overdue balance of <b>${balance}</b>` : '') +
  '. Attached are your past due notice and an account statement.</p>' +
  '<p>Please contact us at 770-248-1444 ext. 2 to arrange payment or discuss any ' +
  'questions regarding your account.</p>' +
  "<p>Best Regards,<br/>Engelman's Bakery<br/>770-248-1444</p>" +
  '</div>';

const attachment = (name, contentBytes) => ({
  '@odata.type': '#microsoft.graph.fileAttachment',
  name,
  contentType: 'application/pdf',
  contentBytes,
});

return {
  json: {
    accountNumber: json.accountNumber,
    accountName: json.accountName,
    recipientEmail: json.recipientEmail,
    addressVariants: json.addressVariants,
    letterPageCount: json.letterPageCount,
    statementPageCount: json.statementPageCount,
    payload: {
      subject: json.accountName
        ? `Engelman's Bakery \u2014 Past Due Balance for ${json.accountName}`
        : `Engelman's Bakery \u2014 Past Due Balance (${json.accountNumber})`,
      body: { contentType: 'HTML', content: html },
      toRecipients: [{ emailAddress: { address: json.recipientEmail } }],
      attachments: [
        attachment(json.letterFileName, json.letterBase64),
        attachment(json.statementFileName, json.statementBase64),
      ],
    },
  },
};
